-- Yardmaster initial schema.
-- Must run unchanged on both SQLite and PostgreSQL: stick to TEXT, BIGINT,
-- INTEGER, BOOLEAN and TIMESTAMP, no database-specific functions or types.
-- IDs are UUID strings generated by the application. Structured values
-- (abilities, rules, limits, tags) are JSON stored as TEXT.
-- Every table has owner_id, created_at and updated_at.
-- No table ever holds prompt or reply content.

CREATE TABLE providers (
    id          TEXT PRIMARY KEY,
    owner_id    TEXT NOT NULL,
    type        TEXT NOT NULL,          -- openai | anthropic | google | openai_compatible
    base_url    TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL
);

CREATE TABLE rule_presets (
    id              TEXT PRIMARY KEY,
    owner_id        TEXT NOT NULL,
    name            TEXT NOT NULL UNIQUE,
    limits          TEXT NOT NULL,      -- JSON: rpm, rph, rpd, tpm, tpd, concurrent
    source_version  TEXT,               -- version of the preset YAML file it came from
    created_at      TIMESTAMP NOT NULL,
    updated_at      TIMESTAMP NOT NULL
);

CREATE TABLE provider_keys (
    id               TEXT PRIMARY KEY,
    owner_id         TEXT NOT NULL,
    provider_id      TEXT NOT NULL REFERENCES providers (id),
    encrypted_key    TEXT NOT NULL,     -- AES-GCM, base64; master key never stored here
    display_name     TEXT NOT NULL,
    enabled          BOOLEAN NOT NULL DEFAULT TRUE,
    abilities        TEXT NOT NULL,     -- JSON
    rule_preset_id   TEXT REFERENCES rule_presets (id),
    rule_overrides   TEXT,              -- JSON
    created_at       TIMESTAMP NOT NULL,
    updated_at       TIMESTAMP NOT NULL
);

CREATE TABLE models (
    id                   TEXT PRIMARY KEY,
    owner_id             TEXT NOT NULL,
    provider_model_name  TEXT NOT NULL,
    provider_key_id      TEXT NOT NULL REFERENCES provider_keys (id),
    abilities            TEXT NOT NULL, -- JSON
    created_at           TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP NOT NULL
);

CREATE TABLE labels (
    id                 TEXT PRIMARY KEY,
    owner_id           TEXT NOT NULL,
    name               TEXT NOT NULL UNIQUE,
    type               TEXT NOT NULL,   -- chat | embedding
    rules              TEXT NOT NULL,   -- JSON: max context, max output, allowed features
    fallback_label_id  TEXT REFERENCES labels (id),
    caller_limits      TEXT,            -- JSON
    created_at         TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP NOT NULL
);

CREATE TABLE pools (
    id           TEXT PRIMARY KEY,
    owner_id     TEXT NOT NULL,
    label_id     TEXT NOT NULL REFERENCES labels (id),
    priority     INTEGER NOT NULL,
    spread_mode  TEXT NOT NULL DEFAULT 'even',  -- even | one_at_a_time
    created_at   TIMESTAMP NOT NULL,
    updated_at   TIMESTAMP NOT NULL,
    UNIQUE (label_id, priority)
);

CREATE TABLE pool_members (
    id               TEXT PRIMARY KEY,
    owner_id         TEXT NOT NULL,
    pool_id          TEXT NOT NULL REFERENCES pools (id),
    model_id         TEXT NOT NULL REFERENCES models (id),
    provider_key_id  TEXT NOT NULL REFERENCES provider_keys (id),
    created_at       TIMESTAMP NOT NULL,
    updated_at       TIMESTAMP NOT NULL
);

CREATE TABLE trusted_issuers (
    id          TEXT PRIMARY KEY,
    owner_id    TEXT NOT NULL,
    name        TEXT NOT NULL,
    issuer      TEXT NOT NULL,
    audience    TEXT NOT NULL,
    public_key  TEXT,
    key_url     TEXT,
    enabled     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL
);

CREATE TABLE caller_limits (
    id                  TEXT PRIMARY KEY,
    owner_id            TEXT NOT NULL,
    label_id            TEXT REFERENCES labels (id),   -- NULL = overall default
    concurrent_default  INTEGER NOT NULL,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL
);

CREATE TABLE settings (
    id          TEXT PRIMARY KEY,
    owner_id    TEXT NOT NULL,
    name        TEXT NOT NULL UNIQUE,
    value       TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL
);

CREATE TABLE admins (
    id             TEXT PRIMARY KEY,
    owner_id       TEXT NOT NULL,
    email          TEXT NOT NULL UNIQUE,
    role           TEXT NOT NULL,       -- admin | read_only
    password_hash  TEXT,                -- Argon2
    mfa_secret     TEXT,
    created_at     TIMESTAMP NOT NULL,
    updated_at     TIMESTAMP NOT NULL
);

-- Append-only: the application never updates or deletes rows here.
CREATE TABLE audit_log (
    id            TEXT PRIMARY KEY,
    owner_id      TEXT NOT NULL,
    admin_id      TEXT REFERENCES admins (id),
    action        TEXT NOT NULL,
    before_value  TEXT,
    after_value   TEXT,
    occurred_at   TIMESTAMP NOT NULL,
    created_at    TIMESTAMP NOT NULL,
    updated_at    TIMESTAMP NOT NULL
);

CREATE TABLE usage_records (
    id                   TEXT PRIMARY KEY,
    owner_id             TEXT NOT NULL,
    caller_id            TEXT NOT NULL,
    label_id             TEXT,
    model_id             TEXT,
    provider_key_id      TEXT,
    tags                 TEXT,          -- JSON array
    tokens_in            BIGINT NOT NULL DEFAULT 0,
    tokens_out           BIGINT NOT NULL DEFAULT 0,
    tokens_cached        BIGINT NOT NULL DEFAULT 0,
    latency_ms           BIGINT,
    status               INTEGER NOT NULL,
    occurred_at          TIMESTAMP NOT NULL,
    created_at           TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP NOT NULL
);

CREATE INDEX idx_usage_records_occurred_at ON usage_records (occurred_at);
CREATE INDEX idx_usage_records_caller ON usage_records (caller_id, occurred_at);
CREATE INDEX idx_usage_records_label ON usage_records (label_id, occurred_at);

CREATE TABLE webhooks (
    id              TEXT PRIMARY KEY,
    owner_id        TEXT NOT NULL,
    url             TEXT NOT NULL,
    events          TEXT NOT NULL,      -- JSON array
    signing_secret  TEXT NOT NULL,
    created_at      TIMESTAMP NOT NULL,
    updated_at      TIMESTAMP NOT NULL
);
